function generatedTarget(exportKey) {
  const candidates = [];
  for (const page of figma.root.children) {
    const boards = page.findAll(
      (node) => node.type === "FRAME" && node.getPluginData("invisible-ui-export") === exportKey,
    );
    for (const board of boards) {
      candidates.push({ page, board });
    }
  }
  const current = candidates.filter((candidate) => candidate.page === figma.currentPage);
  if (current.length > 1)
    throw new Error(
      "Multiple generated boards on this page. Keep one target board per page before updating.",
    );
  return (
    candidates.reverse().find((candidate) => candidate.page === figma.currentPage) ?? candidates[0]
  );
}

const SYNC_PROPERTIES = [
  "fills",
  "strokes",
  "strokeWeight",
  "strokeAlign",
  "cornerRadius",
  "effects",
  "opacity",
  "clipsContent",
  "layoutMode",
  "itemSpacing",
  "paddingTop",
  "paddingBottom",
  "paddingLeft",
  "paddingRight",
  "primaryAxisAlignItems",
  "counterAxisAlignItems",
  "minWidth",
  "minHeight",
  "maxWidth",
  "maxHeight",
  "fontName",
  "fontSize",
  "characters",
  "lineHeight",
  "letterSpacing",
  "textAlignHorizontal",
  "textAlignVertical",
  "textDecoration",
];
const SYNC_SIZING = [
  "primaryAxisSizingMode",
  "counterAxisSizingMode",
  "textAutoResize",
  "layoutAlign",
  "layoutGrow",
];

function nodeState(node) {
  const values = {};
  for (const key of [...SYNC_PROPERTIES, ...SYNC_SIZING]) {
    if (!(key in node)) continue;
    if (typeof node[key] === "symbol")
      throw new Error(`Mixed styles in "${node.name}" need manual review before updating.`);
    values[key] = node[key];
  }
  const bindings = {};
  const corners =
    "topLeftRadius" in node
      ? ["topLeftRadius", "topRightRadius", "bottomLeftRadius", "bottomRightRadius"]
      : ["cornerRadius"];
  for (const key of corners) {
    if (key in node)
      bindings[key] = node.boundVariables?.[key] ?? node.boundVariables?.cornerRadius ?? null;
  }
  return {
    name: node.name,
    values,
    bindings,
    width: node.width,
    height: node.height,
    x: node.x,
    y: node.y,
  };
}

function applyNodeState(node, state, preservePosition = false, boundVariables = new Map()) {
  for (const key of SYNC_PROPERTIES) {
    if (Object.hasOwn(state.values, key)) node[key] = state.values[key];
  }
  // Updating text can rename its layer. Keep the name used for matching on the next run.
  node.name = state.name;
  node.resizeWithoutConstraints(state.width, state.height);
  for (const key of SYNC_SIZING) {
    if (Object.hasOwn(state.values, key)) node[key] = state.values[key];
  }
  for (const [key, alias] of Object.entries(state.bindings)) {
    node.setBoundVariable(key, alias ? boundVariables.get(alias.id) : null);
  }
  if (!preservePosition) {
    node.x = state.x;
    node.y = state.y;
  }
}

function updatePlan(target, source, plan = []) {
  if (target.type !== source.type)
    throw new Error(`Layer type changed for "${source.name}". Update cancelled.`);
  plan.push({ target, before: nodeState(target), after: nodeState(source) });
  if (!("children" in source)) return plan;
  const used = new Set();
  for (const child of source.children) {
    const matches = target.children.filter(
      (candidate) =>
        !used.has(candidate.id) && candidate.name === child.name && candidate.type === child.type,
    );
    if (matches.length !== 1)
      throw new Error(
        `Cannot uniquely match "${child.name}" in "${target.name}". Update cancelled.`,
      );
    used.add(matches[0].id);
    updatePlan(matches[0], child, plan);
  }
  return plan;
}

async function updateGeneratedBoard(target, source, verify = () => {}) {
  // Validate the whole tree before touching existing nodes. Their IDs keep instances connected.
  const plan = updatePlan(target, source);
  const fonts = new Map();
  const boundVariables = new Map();
  for (const item of plan) {
    for (const state of [item.before, item.after]) {
      const font = state.values.fontName;
      if (font) fonts.set(JSON.stringify(font), font);
      for (const alias of Object.values(state.bindings)) {
        if (!alias || boundVariables.has(alias.id)) continue;
        const variable = await figma.variables.getVariableByIdAsync(alias.id);
        if (!variable) throw new Error(`Variable ${alias.id} is unavailable. Update cancelled.`);
        boundVariables.set(alias.id, variable);
      }
    }
  }
  await Promise.all([...fonts.values()].map((font) => figma.loadFontAsync(font)));
  try {
    for (const item of plan)
      applyNodeState(item.target, item.after, item.target === target, boundVariables);
    await verify();
  } catch (error) {
    const failures = [];
    for (const item of plan) {
      try {
        applyNodeState(item.target, item.before, item.target === target, boundVariables);
      } catch (restoreError) {
        failures.push(restoreError);
      }
    }
    if (failures.length)
      throw new Error(`Update failed. Use Undo to restore the previous layout. ${error.message}`);
    throw error;
  }
}

async function updateTokenVariables(payload, collectionName) {
  const collections = (await figma.variables.getLocalVariableCollectionsAsync()).filter(
    (item) => item.name === collectionName,
  );
  if (collections.length > 1)
    throw new Error(
      `Multiple collections named ${collectionName}. Rename duplicates before updating.`,
    );
  let collection = collections[0];
  const existing = collection
    ? (await figma.variables.getLocalVariablesAsync()).filter(
        (item) => item.variableCollectionId === collection.id,
      )
    : [];
  const byName = new Map();
  for (const variable of existing) {
    if (byName.has(variable.name)) throw new Error(`Duplicate variable: ${variable.name}`);
    byName.set(variable.name, variable);
  }
  for (const [name, token] of Object.entries(payload.Light)) {
    if (byName.has(name) && byName.get(name).resolvedType !== token.type)
      throw new Error(`Variable type changed: ${name}. Update cancelled.`);
  }
  if (collection) {
    for (const name of ["Light", "Dark"]) {
      if (collection.modes.filter((mode) => mode.name === name).length > 1)
        throw new Error(`Duplicate mode: ${name}`);
    }
    if (!collection.modes.some((mode) => mode.name === "Light"))
      throw new Error("Rename the existing light mode to Light before updating tokens.");
  }
  const newCollection = !collection;
  const createdVariables = [];
  const createdModes = [];
  const previous = [];
  try {
    if (!collection) {
      collection = figma.variables.createVariableCollection(collectionName);
      collection.renameMode(collection.defaultModeId, "Light");
    }
    const modes = {};
    for (const name of ["Light", "Dark"]) {
      modes[name] = collection.modes.find((mode) => mode.name === name)?.modeId;
      if (!modes[name]) {
        modes[name] = collection.addMode(name);
        createdModes.push(modes[name]);
      }
    }
    for (const [name, token] of Object.entries(payload.Light)) {
      if (!byName.has(name)) {
        const variable = figma.variables.createVariable(name, collection, token.type);
        createdVariables.push(variable);
        byName.set(name, variable);
      }
    }
    for (const [mode, tokens] of Object.entries(payload)) {
      for (const [name, token] of Object.entries(tokens)) {
        const variable = byName.get(name);
        const value = token.alias
          ? { type: "VARIABLE_ALIAS", id: byName.get(token.alias).id }
          : token.value;
        previous.push({ variable, mode: modes[mode], value: variable.valuesByMode[modes[mode]] });
        variable.setValueForMode(modes[mode], value);
      }
    }
  } catch (error) {
    try {
      if (newCollection && collection) collection.remove();
      else {
        for (const item of previous.reverse()) {
          if (!createdVariables.includes(item.variable) && !createdModes.includes(item.mode)) {
            if (item.value === undefined) item.variable.removeValueForMode(item.mode);
            else item.variable.setValueForMode(item.mode, item.value);
          }
        }
        for (const variable of createdVariables) variable.remove();
        for (const mode of createdModes) collection.removeMode(mode);
      }
    } catch {
      throw new Error(`Token update failed. Use Undo to restore the collection. ${error.message}`);
    }
    throw error;
  }
}

function buttonColorTokens(appearance) {
  const output = { Light: {}, Dark: {} };
  for (const [theme, variants] of Object.entries(appearance.themes)) {
    for (const [variant, states] of Object.entries(variants)) {
      for (const [state, style] of Object.entries(states)) {
        for (const property of ["background", "foreground", "border"]) {
          output[theme === "light" ? "Light" : "Dark"][
            `component/button/${variant}/${state}/${property}`
          ] = { type: "COLOR", value: style[property] };
        }
      }
    }
  }
  return output;
}

function buttonPaint(variant, state, property, appearance, variables, bind) {
  const name = `component/button/${variant.toLowerCase()}/${state.toLowerCase()}/${property}`;
  const variable = variables.get(name);
  if (!variable) throw new Error(`Missing generated Button colour: ${name}`);
  const { r, g, b } = appearance.themes.light[variant.toLowerCase()][state.toLowerCase()][property];
  return bind({ type: "SOLID", color: { r, g, b } }, "color", variable);
}

function verifyButtonColors(board, appearance, variables, collection) {
  const byId = new Map([...variables.values()].map((variable) => [variable.id, variable]));
  const components = board.findAll(
    (node) =>
      node.type === "COMPONENT" &&
      node.getPluginData("invisible-ui-source") === "packages/svelte/src/lib/button/Button.svelte",
  );
  const names = new Set();
  let checked = 0;
  const same = (actual, expected, context) => {
    if (typeof actual !== "number" || Math.abs(actual - expected) > 0.00001)
      throw new Error(`Button colour verification failed: ${context}`);
  };
  function paintColor(paints, modeId) {
    if (paints.length !== 1 || paints[0].type !== "SOLID" || paints[0].visible === false)
      throw new Error("Button requires one visible solid paint per property");
    const paint = paints[0];
    let value = paint.boundVariables?.color
      ? byId.get(paint.boundVariables.color.id)?.valuesByMode[modeId]
      : paint.color;
    const seen = new Set();
    while (value?.type === "VARIABLE_ALIAS") {
      if (seen.has(value.id)) throw new Error("Circular Button colour alias");
      seen.add(value.id);
      value = byId.get(value.id)?.valuesByMode[modeId];
    }
    if (!value) throw new Error("Unresolved Button colour");
    // The bound RGBA variable owns alpha; the paint may expose that same alpha.
    return { ...value, a: paint.boundVariables?.color ? (value.a ?? 1) : (paint.opacity ?? 1) };
  }
  for (const component of components) {
    const match = /^Variant=([^,]+), State=(.+)$/.exec(component.name);
    if (!match || names.has(component.name))
      throw new Error("Unexpected or duplicate Button variant");
    names.add(component.name);
    const variant = match[1].toLowerCase();
    const state = match[2].toLowerCase();
    const label = component.children.find((node) => node.name === "Label" && node.type === "TEXT");
    if (!label) throw new Error("Missing Button label");
    for (const theme of ["light", "dark"]) {
      const expected = appearance.themes[theme][variant]?.[state];
      if (!expected) throw new Error(`Unexpected Button state: ${variant}/${state}`);
      const mode = collection.modes.find((item) => item.name.toLowerCase() === theme);
      if (!mode) throw new Error(`Missing ${theme} mode for Button verification`);
      const properties = [
        [component.fills, "background"],
        [component.strokes, "border"],
        [label.fills, "foreground"],
      ];
      const icon = component.children.find((node) => node.name === "Icon");
      if (icon) properties.push([icon.fills, "foreground"]);
      for (const [paints, property] of properties) {
        const actual = paintColor(paints, mode.modeId);
        for (const channel of ["r", "g", "b", "a"])
          same(
            actual[channel],
            expected[property][channel],
            `${variant}/${state}/${theme}/${property}/${channel}`,
          );
      }
      same(component.opacity, expected.opacity, `${variant}/${state}/opacity`);
      same(component.strokeWeight, expected.borderWidth, `${variant}/${state}/border width`);
      if (label.textDecoration !== (expected.underline ? "UNDERLINE" : "NONE"))
        throw new Error(`Button text decoration differs: ${variant}/${state}`);
      checked++;
    }
  }
  if (checked !== 30) throw new Error(`Expected 30 Button colour cases, verified ${checked}`);
  return checked;
}

const COLLECTION_NAME = "Invisible UI";
const EXPORT_KEY = "invisible-ui-component-pilot";

const FONT_REGULAR = { family: "Inter", style: "Regular" };
const FONT_MEDIUM = { family: "Inter", style: "Medium" };
const FONT_SEMIBOLD = { family: "Inter", style: "Semi Bold" };

let variables = new Map();
let generatedNodes = [];

function remember(node) {
  generatedNodes.push(node);
  return node;
}

function removeGeneratedNodes() {
  for (const node of generatedNodes) {
    if (!node.removed) node.remove();
  }
  generatedNodes = [];
}

function rgb(hex) {
  const digits = hex.replace("#", "");
  return {
    r: Number.parseInt(digits.slice(0, 2), 16) / 255,
    g: Number.parseInt(digits.slice(2, 4), 16) / 255,
    b: Number.parseInt(digits.slice(4, 6), 16) / 255,
  };
}

function solid(hex, opacity = 1) {
  return { type: "SOLID", color: rgb(hex), opacity };
}

function paintFor(variableName, fallback, opacity = 1) {
  const paint = solid(fallback, opacity);
  const variable = variables.get(variableName);
  return variable ? figma.variables.setBoundVariableForPaint(paint, "color", variable) : paint;
}

function fill(node, variableName, fallback, opacity = 1) {
  node.fills = [paintFor(variableName, fallback, opacity)];
}

function stroke(node, variableName, fallback) {
  node.strokes = [paintFor(variableName, fallback)];
  node.strokeWeight = 1;
  node.strokeAlign = "INSIDE";
}

function radius(node, variableName, fallback) {
  node.cornerRadius = fallback;
  const variable = variables.get(variableName);
  if (variable) node.setBoundVariable("cornerRadius", variable);
}

function auto(node, direction, gap = 0) {
  node.layoutMode = direction;
  node.primaryAxisSizingMode = "AUTO";
  node.counterAxisSizingMode = "AUTO";
  node.itemSpacing = gap;
}

function pad(node, vertical, horizontal = vertical) {
  node.paddingTop = vertical;
  node.paddingBottom = vertical;
  node.paddingLeft = horizontal;
  node.paddingRight = horizontal;
}

function text(value, options = {}) {
  const node = remember(figma.createText());
  node.fontName = options.font ?? FONT_REGULAR;
  node.characters = value;
  node.fontSize = options.size ?? 14;
  node.lineHeight = { unit: "AUTO" };
  fill(node, options.color ?? "role/color-text", options.fallback ?? "#282420");
  return node;
}

function title(value) {
  return text(value, { font: FONT_SEMIBOLD, size: 20 });
}

function group(label) {
  const frame = remember(figma.createFrame());
  frame.name = label;
  auto(frame, "VERTICAL", 16);
  frame.fills = [];
  frame.appendChild(title(label));
  const row = remember(figma.createFrame());
  row.name = `${label} examples`;
  auto(row, "HORIZONTAL", 24);
  row.fills = [];
  frame.appendChild(row);
  return { frame, row };
}

function component(name, source) {
  const node = remember(figma.createComponent());
  node.name = name;
  node.setPluginData("invisible-ui-source", source);
  node.setPluginData("invisible-ui-export", EXPORT_KEY);
  return node;
}

function componentSet(name, source, components, columns) {
  const set = remember(figma.combineAsVariants(components, components[0].parent));
  set.name = name;
  set.description = `Generated from ${source}.`;
  set.setPluginData("invisible-ui-source", source);
  set.setPluginData("invisible-ui-export", EXPORT_KEY);
  set.fills = [];
  set.strokes = [];

  const gap = 24;
  const padding = 24;
  const rows = Math.ceil(components.length / columns);
  const columnWidths = Array.from({ length: columns }, () => 0);
  const rowHeights = Array.from({ length: rows }, () => 0);

  components.forEach((item, index) => {
    const column = index % columns;
    const row = Math.floor(index / columns);
    columnWidths[column] = Math.max(columnWidths[column], item.width);
    rowHeights[row] = Math.max(rowHeights[row], item.height);
  });

  const columnOffsets = columnWidths.map((_, index) =>
    columnWidths.slice(0, index).reduce((sum, width) => sum + width + gap, padding),
  );
  const rowOffsets = rowHeights.map((_, index) =>
    rowHeights.slice(0, index).reduce((sum, height) => sum + height + gap, padding),
  );

  components.forEach((item, index) => {
    item.x = columnOffsets[index % columns];
    item.y = rowOffsets[Math.floor(index / columns)];
  });

  const width = columnWidths.reduce((sum, value) => sum + value, padding * 2 + gap * (columns - 1));
  const height = rowHeights.reduce((sum, value) => sum + value, padding * 2 + gap * (rows - 1));
  set.resizeWithoutConstraints(width, height);
  return set;
}

function addIcon(parent, colorName, fallback, glyph = "+") {
  const icon = text(glyph, { font: FONT_MEDIUM, size: 16, color: colorName, fallback });
  icon.name = "Icon";
  parent.appendChild(icon);
}

function createButton(variant, state) {
  const node = component(
    `Variant=${variant}, State=${state}`,
    "packages/svelte/src/lib/button/Button.svelte",
  );
  auto(node, "HORIZONTAL", 8);
  pad(node, 8, 14);
  node.counterAxisAlignItems = "CENTER";
  node.primaryAxisAlignItems = "CENTER";
  node.minHeight = 36;
  const appearance = BUTTON_APPEARANCE.themes.light[variant.toLowerCase()][state.toLowerCase()];
  const paint = (property) =>
    buttonPaint(variant, state, property, BUTTON_APPEARANCE, variables, (value, field, variable) =>
      figma.variables.setBoundVariableForPaint(value, field, variable),
    );
  node.opacity = appearance.opacity;
  radius(node, "radius/control", 8);

  node.fills = [paint("background")];
  node.strokes = [paint("border")];
  node.strokeWeight = appearance.borderWidth;
  node.strokeAlign = "INSIDE";

  if (variant === "Danger") {
    addIcon(node, "role/color-text", "#000000", "!");
    node.children[0].fills = [paint("foreground")];
  }
  const label = text(variant, {
    font: FONT_MEDIUM,
  });
  label.fills = [paint("foreground")];
  label.textDecoration = appearance.underline ? "UNDERLINE" : "NONE";
  label.name = "Label";
  node.appendChild(label);
  return node;
}

function createField(state) {
  const node = component(`State=${state}`, "packages/svelte/src/lib/text-field/TextField.svelte");
  auto(node, "VERTICAL", 6);
  node.resize(288, 100);
  node.counterAxisSizingMode = "FIXED";
  node.fills = [];

  const label = text("Label", { font: FONT_SEMIBOLD, size: 14 });
  label.name = "Label";
  if (state === "Disabled") {
    fill(label, "role/color-text-disabled", "#757067");
  }
  node.appendChild(label);

  const control = remember(figma.createFrame());
  control.name = "Control";
  auto(control, "HORIZONTAL", 8);
  control.counterAxisSizingMode = "FIXED";
  control.primaryAxisSizingMode = "FIXED";
  control.resize(288, 40);
  control.counterAxisAlignItems = "CENTER";
  pad(control, 8, 12);
  fill(control, "role/color-background", "#FFFFFF");
  radius(control, "radius/control", 8);
  const border =
    state === "Error"
      ? ["role/color-danger", "#BE3B50"]
      : state === "Focus"
        ? ["role/color-focus-ring", "#8E6CD4"]
        : ["role/color-control-border", "#757067"];
  stroke(control, ...border);
  if (state === "Focus") {
    control.effects = [
      {
        type: "DROP_SHADOW",
        color: { ...rgb("#8E6CD4"), a: 0.3 },
        offset: { x: 0, y: 0 },
        radius: 3,
        spread: 2,
        visible: true,
        blendMode: "NORMAL",
      },
    ];
  }
  const value = text(state === "Default" ? "Placeholder" : "Entered value", {
    color: state === "Default" ? "role/color-text-secondary" : "role/color-text",
    fallback: state === "Default" ? "#524C44" : "#282420",
  });
  value.name = "Value";
  if (state === "Disabled") fill(value, "role/color-text-disabled", "#757067");
  control.appendChild(value);
  node.appendChild(control);

  const messages = {
    Default: ["Helpful description", "role/color-text-secondary", "#524C44"],
    Focus: ["Helpful description", "role/color-text-secondary", "#524C44"],
    Error: ["Error message", "role/color-danger-body-text", "#BE3B50"],
    Success: ["Value confirmed", "role/color-success-body-text", "#3E7523"],
    Disabled: ["Unavailable", "role/color-text-disabled", "#757067"],
  };
  const [message, color, fallback] = messages[state];
  const caption = text(message, { size: 13, color, fallback });
  caption.name = state === "Error" ? "Error" : state === "Success" ? "Success" : "Description";
  node.appendChild(caption);
  return node;
}

function cardShell(name) {
  const node = component(name, "packages/svelte/src/lib/card/Card.svelte");
  fill(node, "role/color-background", "#FFFFFF");
  stroke(node, "role/color-border", "#C7C1B7");
  radius(node, "radius/surface", 12);
  node.clipsContent = true;
  return node;
}

function cardBody(width = 320) {
  const body = remember(figma.createFrame());
  body.name = "Body";
  auto(body, "VERTICAL", CARD_LAYOUT.body.gap);
  body.counterAxisSizingMode = "FIXED";
  body.resize(width, 110);
  pad(body, CARD_LAYOUT.body.padding);
  body.fills = [];
  body.appendChild(text("Card title", { font: FONT_SEMIBOLD, size: 17 }));
  const description = text("Supporting content from the component description.", {
    color: "role/color-text-secondary",
    fallback: "#524C44",
  });
  description.textAutoResize = "HEIGHT";
  description.resize(width - CARD_LAYOUT.body.padding * 2, 40);
  body.appendChild(description);
  description.layoutAlign = "STRETCH";
  return body;
}

function mediaPlaceholder(width, height) {
  const media = remember(figma.createFrame());
  media.name = "Media";
  fill(media, "role/color-neutral-surface", "#F4F2EF");
  media.layoutMode = "HORIZONTAL";
  // Enabling auto layout defaults to hug, which would collapse the media to its label.
  media.primaryAxisSizingMode = "FIXED";
  media.counterAxisSizingMode = "FIXED";
  media.resize(width, height);
  media.primaryAxisAlignItems = CARD_LAYOUT.media.justify;
  media.counterAxisAlignItems = CARD_LAYOUT.media.align;
  media.appendChild(
    text("Media", { font: FONT_MEDIUM, color: "role/color-text-secondary", fallback: "#524C44" }),
  );
  return media;
}

function createVerticalCard() {
  const node = cardShell("Variant=Media, Orientation=Vertical");
  auto(node, CARD_LAYOUT.vertical.direction);
  node.resizeWithoutConstraints(320, node.height);
  node.counterAxisSizingMode = "FIXED";
  const media = mediaPlaceholder(320, 140);
  const body = cardBody();
  node.appendChild(media);
  node.appendChild(body);
  media.layoutAlign = CARD_LAYOUT.vertical.mediaAlign;
  body.layoutAlign = "STRETCH";
  return node;
}

function createHorizontalCard() {
  const node = cardShell("Variant=Media, Orientation=Horizontal");
  auto(node, CARD_LAYOUT.horizontal.direction);
  node.counterAxisAlignItems = "MIN";
  const media = mediaPlaceholder(CARD_LAYOUT.horizontal.mediaWidth, 150);
  const body = cardBody(300);
  node.appendChild(media);
  node.appendChild(body);
  // The body determines the card height; media fills it while keeping its width.
  media.layoutAlign = CARD_LAYOUT.horizontal.mediaAlign;
  return node;
}

function createDashboardCard() {
  const node = cardShell("Variant=Dashboard, Orientation=None");
  auto(node, "VERTICAL", 20);
  pad(node, 18);
  node.resize(300, 140);
  node.appendChild(text("Monthly activity", { font: FONT_SEMIBOLD, size: 15 }));
  const metric = remember(figma.createFrame());
  metric.name = "Metric";
  auto(metric, "HORIZONTAL", 8);
  metric.counterAxisAlignItems = "BASELINE";
  metric.fills = [];
  metric.appendChild(text("1,284", { font: FONT_SEMIBOLD, size: 30 }));
  metric.appendChild(
    text("+12%", { font: FONT_MEDIUM, color: "role/color-success-body-text", fallback: "#3E7523" }),
  );
  node.appendChild(metric);
  return node;
}

async function localVariables() {
  const collections = await figma.variables.getLocalVariableCollectionsAsync();
  const collection = collections.find((item) => item.name === COLLECTION_NAME);
  if (!collection) throw new Error(`Variable collection "${COLLECTION_NAME}" was not found.`);
  const all = await figma.variables.getLocalVariablesAsync();
  return new Map(
    all
      .filter((variable) => variable.variableCollectionId === collection.id)
      .map((variable) => [variable.name, variable]),
  );
}

async function main() {
  await Promise.all([
    figma.loadFontAsync(FONT_REGULAR),
    figma.loadFontAsync(FONT_MEDIUM),
    figma.loadFontAsync(FONT_SEMIBOLD),
  ]);
  await localVariables();
  await updateTokenVariables(BUTTON_PAINTS, COLLECTION_NAME);
  variables = await localVariables();
  const collection = (await figma.variables.getLocalVariableCollectionsAsync()).find(
    (item) => item.name === COLLECTION_NAME,
  );

  const page = figma.currentPage;
  const target = generatedTarget(EXPORT_KEY);
  generatedNodes = [];

  try {
    const board = remember(figma.createFrame());
    board.visible = !target;
    board.name = "Invisible UI component pilot";
    auto(board, "VERTICAL", 48);
    pad(board, 48);
    fill(board, "role/color-background", "#FFFFFF");
    board.appendChild(title("Invisible UI component pilot"));
    board.appendChild(
      text(
        "Editable component structures generated from the Svelte contracts and connected to shared variables.",
        {
          color: "role/color-text-secondary",
          fallback: "#524C44",
        },
      ),
    );

    const buttons = group("Button");
    const buttonComponents = [];
    for (const variant of ["Default", "Primary", "Secondary", "Ghost", "Danger"]) {
      for (const state of ["Default", "Hover", "Disabled"]) {
        const item = createButton(variant, state);
        buttons.row.appendChild(item);
        buttonComponents.push(item);
      }
    }
    componentSet("Button", "packages/svelte/src/lib/button/Button.svelte", buttonComponents, 3);
    board.appendChild(buttons.frame);

    const fields = group("Text Field");
    const fieldComponents = [];
    for (const state of ["Default", "Focus", "Error", "Success", "Disabled"]) {
      const item = createField(state);
      fields.row.appendChild(item);
      fieldComponents.push(item);
    }
    componentSet(
      "Text Field",
      "packages/svelte/src/lib/text-field/TextField.svelte",
      fieldComponents,
      5,
    );
    board.appendChild(fields.frame);

    const cards = group("Card");
    const cardComponents = [createVerticalCard(), createHorizontalCard(), createDashboardCard()];
    for (const item of cardComponents) cards.row.appendChild(item);
    componentSet("Card", "packages/svelte/src/lib/card/Card.svelte", cardComponents, 3);
    board.appendChild(cards.frame);

    board.setPluginData("invisible-ui-export", EXPORT_KEY);
    page.appendChild(board);
    if (target) {
      await updateGeneratedBoard(target.board, board, () =>
        verifyButtonColors(target.board, BUTTON_APPEARANCE, variables, collection),
      );
      removeGeneratedNodes();
      if (target.page === page) {
        page.selection = [target.board];
        figma.viewport.scrollAndZoomIntoView([target.board]);
      }
      figma.closePlugin(
        `Updated 3 component sets on ${target.page.name}. Button colours verified in Light and Dark.`,
      );
    } else {
      verifyButtonColors(board, BUTTON_APPEARANCE, variables, collection);
      generatedNodes = [];
      figma.currentPage.selection = [board];
      figma.viewport.scrollAndZoomIntoView([board]);
      figma.closePlugin(`Created 3 component sets with 23 variants on ${page.name}.`);
    }
  } catch (error) {
    removeGeneratedNodes();
    throw error;
  }
}

figma.showUI(__html__, { width: 380, height: 440, themeColors: true });
let running = false;
figma.ui.onmessage = async (message) => {
  if (running || !message) return;
  if (message.type === "ready") {
    figma.ui.postMessage({ type: "token-info", ...TOKEN_INFO });
    return;
  }
  if (message.type === "cancel") {
    figma.closePlugin();
    return;
  }
  if (message.type !== "update" || typeof message.includeTokens !== "boolean") return;
  running = true;
  let tokensUpdated = false;
  try {
    if (message.includeTokens) {
      await updateTokenVariables(TOKEN_PAYLOAD, COLLECTION_NAME);
      tokensUpdated = true;
    }
    await main();
  } catch (error) {
    console.error(error);
    figma.ui.postMessage({
      type: "error",
      message: `${tokensUpdated ? "Tokens updated; component update failed. " : ""}${error instanceof Error ? error.message : "Update failed."}`,
    });
  } finally {
    running = false;
  }
};
